{
  "hypothesis": "When small-cap stocks experience abnormally high-volume days, short-term reversals follow in next-period cross-sectional returns.",
  "factors": [
    {
      "name": "Volume Reversal Rank",
      "expression": "RANK(TS_ZSCORE($volume, 10) - TS_ZSCORE($volume, 20))",
      "explanation": "Measures the difference in volume volatility between short and medium horizons, intended to capture reversal dynamics after extreme volume events."
    },
    {
      "name": "High Volume Residuals",
      "expression": "REGRESI($return, $volume, 20) - MEAN($return, 20)",
      "explanation": "Uses regression residuals of returns on volume to isolate unexpected returns following high-volume activity, testing for reversal patterns."
    },
    {
      "name": "Volume Dispersion Signal",
      "expression": "TS_QUANTILE($volume, 20, 0.9) - TS_QUANTILE($volume, 20, 0.1)",
      "explanation": "Calculates the spread between upper and lower volume quantiles over a 20-day window to identify extreme volume regimes linked to reversals."
    },
    {
      "name": "Volume-Return Asymmetry",
      "expression": "FILTER($return, $volume > TS_MEAN($volume, 10)) * DELTA($volume, 10)",
      "explanation": "Gates returns on high-volume days and multiplies by volume change, exploring directional shifts after volume spikes."
    },
    {
      "name": "Volume Skew Factor",
      "expression": "SKEW(TS_ZSCORE($volume, 10)) * TS_PCTCHANGE($return, 10)",
      "explanation": "Combines volume skew with return momentum to test if asymmetric volume distributions predict short-term reversals."
    },
    {
      "name": "Volume Residual Spread",
      "expression": "TS_MAD($return, 20) - TS_MAD($volume, 20)",
      "explanation": "Compares the dispersion of returns and volume to detect mismatched volatility regimes that may precede reversals."
    }
  ]
}

